using Azurite.NormalEditor.Entry;

static class TickCallbackChecks
{
    internal static void Run(Action<string,Action> test,Action<bool,string> need)
    {
        test("Update lifecycle permits one observation only after original return and finalization",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,true);need(!f.Gate.Ready,"Update return invented ready");need(calls.TryComplete(token,stamp,200,null)&&f.Gate.Failure is null&&!f.Gate.Ready,"genuine Update completion rejected or invented readiness");var next=calls.Enter(f.Stamp(12,6,0),200);calls.Returned(next,f.Stamp(12,7,0),200,true);need(calls.TryComplete(next,f.Stamp(12,8,0),200,null),"following natural Update rejected");});
        test("Update finalizer cannot substitute for missing prefix",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);need(!calls.TryComplete(null,f.Stamp(11,5,0),200,null)&&f.Gate.Failure is not null,"missing prefix accepted");});
        test("Update finalizer requires actual original return",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);need(!calls.TryComplete(token,stamp,200,null)&&f.Gate.Failure is not null,"missing return accepted");});
        test("duplicate Update return latches failure before observation",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,true);calls.Returned(token,stamp,200,true);need(!calls.TryComplete(token,stamp,200,null)&&f.Gate.Failure is not null,"duplicate return accepted");});
        test("duplicate Update finalizer cannot issue a second observation",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,true);need(calls.TryComplete(token,stamp,200,null),"first finalizer refused");need(!calls.TryComplete(token,stamp,200,null)&&f.Gate.Failure is not null,"duplicate completion accepted");});
        test("following Update cannot bypass outstanding finalizer",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,true);need(calls.Enter(stamp,200) is null&&f.Gate.Failure is not null,"outstanding completion bypassed");});
        test("suppressed Update cannot be used as a main-thread tick",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,false);need(!calls.TryComplete(token,stamp,200,null)&&f.Gate.Failure is not null,"suppressed Update accepted");});
        test("exceptional Update never issues a ready observation",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);var error=new InvalidOperationException("native-update-error");need(!calls.TryComplete(token,stamp,200,error)&&f.Gate.Failure!.Contains("native-update-error"),"original Update exception lost");});
        test("foreign Update token cannot issue an observation",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var other=new CatalogTickCallbacks(new Fixture().Gate);var stamp=f.Stamp(11,5,0);var foreign=other.Enter(stamp,200);calls.Enter(stamp,200);calls.Returned(foreign,stamp,200,true);need(f.Gate.Failure is not null,"foreign token accepted");});
        foreach(var field in new[]{"run","process","managed-thread","native-thread","owner"})test("Update return refuses mismatched "+field,()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);var changed=field switch{"run"=>stamp with{RunId="11111111-1111-1111-1111-111111111111"},"process"=>stamp with{ProcessId=43},"managed-thread"=>stamp with{ManagedThreadId=9},"native-thread"=>stamp with{NativeThreadId=99},_=>stamp};calls.Returned(token,changed,field=="owner"?201:200,true);need(!calls.TryComplete(token,stamp,200,null)&&f.Gate.Failure is not null,"changed callback identity accepted");});
        test("Update workbench cannot rebind between native ticks",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(11,5,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,true);need(calls.TryComplete(token,stamp,200,null),"first Update failed");need(calls.Enter(f.Stamp(12,6,0),201) is null&&f.Gate.Failure is not null,"workbench silently rebound");});
        test("Update cannot complete in a different native frame",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var token=calls.Enter(f.Stamp(11,5,0),200);calls.Returned(token,f.Stamp(12,6,0),200,true);need(f.Gate.Failure is not null,"cross-frame callback accepted");});
        test("late Update callback latches the configured deadline",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var token=calls.Enter(f.Stamp(11,5,0),200);calls.Returned(token,f.Stamp(11,101,0),200,true);need(f.Gate.Failure is not null,"late Update accepted");});
        test("Update clock cannot reverse inside original completion",()=>{var f=new Fixture();var calls=new CatalogTickCallbacks(f.Gate);var token=calls.Enter(f.Stamp(11,5,0),200);calls.Returned(token,f.Stamp(11,4,0),200,true);need(f.Gate.Failure is not null,"reversed Update clock accepted");});
        test("completed readiness does not time out on later healthy Update",()=>{var f=new Fixture();f.Start();f.Tick();var calls=new CatalogTickCallbacks(f.Gate);var stamp=f.Stamp(1200,1000,0);var token=calls.Enter(stamp,200);calls.Returned(token,stamp,200,true);need(calls.TryComplete(token,stamp,200,null)&&f.Gate.Ready&&f.Gate.Failure is null,"completed readiness timed out");});
        test("evidence sink cannot reenter Update lifecycle tracking",()=>{var events=new List<CatalogEvidence>();CatalogTickCallbacks? calls=null;CatalogTickFrame? token=null;var gate=new CatalogReadiness(Fixture.Binding,e=>{events.Add(e);if(e.Kind=="catalog-start-return")token=calls!.Enter(e.Stamp,200);});calls=new(gate);var f=new Fixture(gate,events);f.Start();need(token is null&&gate.Failure is not null&&!gate.Ready,"sink manufactured Update prefix");});
    }
}
